// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

contract ErrorHandaling {

    error notOwner();
    function diposit (uint _value) public {
        if (_value == 0){
            revert("0 not allwed");
        }else if (_value >= 100){
            revert("Too High Value");
        }else if (msg.sender == address(0)){
            revert("not valid Address");
        }
    }
}

